import { beforeEach, describe, expect, it, vi } from "vitest";
import type { Prisma } from "@/generated/prisma/client";
import { SubscriptionStatus } from "@/generated/prisma/enums";
import { AppError } from "@/lib/errors";
const mocks = vi.hoisted(() => ({
  user: { findUnique: vi.fn() },
  systemControl: { findUnique: vi.fn() },
}));
vi.mock("@/lib/db", () => ({ db: mocks }));
import {
  canUser,
  getEffectivePlan,
  getClientEntitlements,
  requireEntitlement,
  EntitlementError,
  type EntitlementUser,
  type EntitlementFeature,
} from "@/lib/entitlements";

const start = new Date("2026-10-01T00:00:00Z");
const now = new Date("2026-10-16T00:00:00Z");
const end = new Date("2026-11-01T00:00:00Z");
const grace = new Date("2026-11-04T00:00:00Z");
const before = (date: Date) => new Date(date.getTime() - 1);
const control = { sendingEnabled: true, paidGatingEnabled: true };
const legacy = { ...control, paidGatingEnabled: false };
const features: EntitlementFeature[] = [
  "send",
  "templateCreate",
  "templateEdit",
  "templateUse",
  "resumeUpload",
  "manualRepeatSend",
  "historyShortlist",
  "markReplied",
  "csvImport",
  "followUpReminders",
  "prioritySupport",
  "blackThemes",
  "previewHighlightColors",
  "recipientRoleOverride",
];
const legacyFeatures: EntitlementFeature[] = [
  "historyShortlist",
  "markReplied",
  "csvImport",
  "followUpReminders",
];
function user(overrides: Partial<EntitlementUser> = {}): EntitlementUser {
  return {
    id: "owner",
    plan: "FREE",
    subscriptionStatus: "NONE",
    currentPeriodStart: null,
    currentPeriodEnd: null,
    dodoSubscriptionId: null,
    gracePeriodEnd: null,
    planOverride: null,
    planOverrideStartsAt: null,
    planOverrideExpiresAt: null,
    grandfatheredUntil: null,
    isSuspended: false,
    deletionRequestedAt: null,
    gmailAuthorized: true,
    ...overrides,
  };
}
function paid(overrides: Partial<EntitlementUser> = {}) {
  return user({
    plan: "PAID",
    subscriptionStatus: "ACTIVE",
    dodoSubscriptionId: "sub",
    currentPeriodStart: start,
    currentPeriodEnd: end,
    ...overrides,
  });
}

describe("effective plans", () => {
  it("defaults to Free and verifies subscription identity, plan and period", () => {
    expect(getEffectivePlan(user(), now)).toBe("FREE");
    for (const patch of [
      { plan: "FREE" as const },
      { dodoSubscriptionId: null },
      { dodoSubscriptionId: "" },
      { currentPeriodStart: null },
      { currentPeriodEnd: null },
      { currentPeriodStart: end },
      { currentPeriodEnd: start },
    ])
      expect(getEffectivePlan(paid(patch), now)).toBe("FREE");
  });
  it.each(Object.values(SubscriptionStatus))(
    "handles %s without inferred grace",
    (status) => {
      expect(getEffectivePlan(paid({ subscriptionStatus: status }), now)).toBe(
        status === "ACTIVE" ? "PAID" : "FREE",
      );
    },
  );
  it("uses inclusive starts and exclusive ends, including scheduled cancellation", () => {
    const scheduled = { ...paid(), cancelAtPeriodEnd: true };
    expect(getEffectivePlan(scheduled, before(start))).toBe("FREE");
    expect(getEffectivePlan(scheduled, start)).toBe("PAID");
    expect(getEffectivePlan(scheduled, before(end))).toBe("PAID");
    expect(getEffectivePlan(scheduled, end)).toBe("FREE");
  });
  it("requires explicit valid PAST_DUE grace with an exclusive deadline", () => {
    const overdue = paid({
      subscriptionStatus: "PAST_DUE",
      gracePeriodEnd: grace,
    });
    expect(getEffectivePlan(overdue, before(start))).toBe("FREE");
    expect(getEffectivePlan(overdue, end)).toBe("PAID");
    expect(getEffectivePlan(overdue, before(grace))).toBe("PAID");
    expect(getEffectivePlan(overdue, grace)).toBe("FREE");
    for (const deadline of [null, before(end), end]) {
      expect(
        getEffectivePlan({ ...overdue, gracePeriodEnd: deadline }, end),
      ).toBe("FREE");
    }
    expect(getEffectivePlan(paid({ gracePeriodEnd: grace }), end)).toBe("FREE");
  });
  it("applies timed and permanent overrides ahead of grandfathering and subscription", () => {
    const override = paid({
      planOverride: "FREE",
      planOverrideStartsAt: start,
      planOverrideExpiresAt: end,
      grandfatheredUntil: grace,
    });
    expect(getEffectivePlan(override, before(start))).toBe("PAID");
    expect(getEffectivePlan(override, start)).toBe("FREE");
    expect(getEffectivePlan(override, before(end))).toBe("FREE");
    expect(getEffectivePlan(override, end)).toBe("PAID");
    expect(
      getEffectivePlan(
        user({ planOverride: "PAID", planOverrideStartsAt: start }),
        now,
      ),
    ).toBe("PAID");
    expect(getEffectivePlan(user({ planOverride: "PAID" }), now)).toBe("FREE");
    expect(
      getEffectivePlan(user({ grandfatheredUntil: end }), before(end)),
    ).toBe("PAID");
    expect(getEffectivePlan(user({ grandfatheredUntil: end }), end)).toBe(
      "FREE",
    );
  });
});

describe("feature decisions and safe client DTO", () => {
  it("denies all features on deletion, suspension and missing controls; admin cannot bypass", () => {
    for (const patch of [
      { deletionRequestedAt: now, isSuspended: true },
      { isSuspended: true },
    ]) {
      const blocked = {
        ...paid(patch),
        isAdmin: true,
        planOverride: "PAID" as const,
        planOverrideStartsAt: start,
      };
      expect(getEffectivePlan(blocked, now)).toBe("FREE");
      for (const feature of features)
        expect(canUser(blocked, feature, legacy, now)).toEqual({
          allowed: false,
          reason: patch.deletionRequestedAt
            ? "ACCOUNT_UNAVAILABLE"
            : "ACCOUNT_SUSPENDED",
        });
    }
    for (const feature of features)
      expect(canUser(paid(), feature, null, now)).toEqual({
        allowed: false,
        reason: "SYSTEM_CONTROL_UNAVAILABLE",
      });
    const admin = { ...user(), isAdmin: true };
    expect(canUser(admin, "prioritySupport", legacy, now).allowed).toBe(false);
  });
  it("preserves legacy access until gating is enabled, excluding priority support", () => {
    for (const feature of legacyFeatures) {
      expect(canUser(user(), feature, legacy, now).allowed).toBe(true);
      expect(canUser(user(), feature, control, now)).toEqual({
        allowed: false,
        reason: "UPGRADE_REQUIRED",
      });
      expect(canUser(paid(), feature, control, now).allowed).toBe(true);
    }
    expect(canUser(user(), "prioritySupport", legacy, now).allowed).toBe(false);
    for (const feature of features) {
      expect(canUser(paid(), feature, control, now).allowed).toBe(true);
    }
  });
  it("includes manual repeat sends on both plans and after downgrade", () => {
    for (const settings of [control, legacy]) {
      for (const account of [user(), paid(), paid({ currentPeriodEnd: now })]) {
        expect(canUser(account, "manualRepeatSend", settings, now)).toEqual({
          allowed: true,
          reason: null,
        });
      }
    }
  });
  it("keeps recipient-role overrides Premium-only regardless of rollout gating", () => {
    for (const settings of [control, legacy]) {
      expect(canUser(user(), "recipientRoleOverride", settings, now)).toEqual({
        allowed: false,
        reason: "UPGRADE_REQUIRED",
      });
      expect(
        canUser(paid(), "recipientRoleOverride", settings, now).allowed,
      ).toBe(true);
    }
  });
  it("enforces sending controls and Gmail independently of paid gating", () => {
    for (const paidGatingEnabled of [true, false]) {
      expect(
        canUser(
          paid(),
          "send",
          { sendingEnabled: false, paidGatingEnabled },
          now,
        ),
      ).toEqual({ allowed: false, reason: "SENDING_DISABLED" });
      expect(
        canUser(
          user({ gmailAuthorized: false }),
          "send",
          { sendingEnabled: true, paidGatingEnabled },
          now,
        ),
      ).toEqual({ allowed: false, reason: "GMAIL_RECONNECT_REQUIRED" });
      expect(
        canUser(
          user(),
          "send",
          { sendingEnabled: true, paidGatingEnabled },
          now,
        ).allowed,
      ).toBe(true);
    }
  });
  it("returns only the exact allowlisted client shape even with injected raw fields", () => {
    const raw = {
      ...user(),
      encryptedRefreshToken: "[REDACTED_SECRET]",
      googleId: "private",
      suspensionReason: "private",
      billingCountry: "US",
      isAdmin: true,
    };
    expect(getClientEntitlements(raw, control, now)).toEqual({
      gmailPause: null,
      effectivePlan: "FREE",
      accessDeadline: null,
      planConfigVersion: 5,
      paidGatingEnabled: true,
      controlsAvailable: true,
      limits: {
        roleShortcuts: 2,
        monthlyEmails: 15,
        dailyEmails: 3,
        campaignRecipients: 3,
        savedTemplates: 1,
      },
      tracking: "basic",
      features: {
        send: true,
        templateCreate: true,
        templateEdit: true,
        templateUse: true,
        resumeAttachment: true,
        manualRepeatSend: true,
        historyShortlist: false,
        markReplied: false,
        csvImport: false,
        followUpReminders: false,
        prioritySupport: false,
        blackThemes: false,
        previewHighlightColors: false,
        recipientRoleOverride: false,
      },
      followUpDelayOptions: [],
      reasons: {
        send: null,
        templateCreate: null,
        templateEdit: null,
        templateUse: null,
        resumeUpload: null,
        manualRepeatSend: null,
        historyShortlist: "UPGRADE_REQUIRED",
        markReplied: "UPGRADE_REQUIRED",
        csvImport: "UPGRADE_REQUIRED",
        followUpReminders: "UPGRADE_REQUIRED",
        prioritySupport: "UPGRADE_REQUIRED",
        blackThemes: "UPGRADE_REQUIRED",
        previewHighlightColors: "UPGRADE_REQUIRED",
        recipientRoleOverride: "UPGRADE_REQUIRED",
      },
    });
    expect(getClientEntitlements(user(), legacy, now).limits).toEqual({
      roleShortcuts: 2,
      monthlyEmails: null,
      dailyEmails: 200,
      campaignRecipients: 10,
      savedTemplates: null,
    });
    expect(
      getClientEntitlements(user(), legacy, now).followUpDelayOptions,
    ).toEqual([3, 7, 14]);
    expect(
      getClientEntitlements(paid(), control, now).limits.savedTemplates,
    ).toBeNull();
    const missing = getClientEntitlements(paid(), null, now);
    expect(missing.controlsAvailable).toBe(false);
    expect(Object.values(missing.features).every((value) => !value)).toBe(true);
    expect(missing.followUpDelayOptions).toEqual([]);
  });
});

describe("trusted entitlement reads", () => {
  beforeEach(() => {
    vi.resetAllMocks();
    mocks.user.findUnique.mockResolvedValue(user());
    mocks.systemControl.findUnique.mockResolvedValue(legacy);
  });
  it("reloads scoped state on each call using only the narrow selection and no writes", async () => {
    await requireEntitlement("owner", "csvImport");
    expect(mocks.user.findUnique).toHaveBeenCalledWith({
      where: { id: "owner" },
      select: {
        id: true,
        plan: true,
        subscriptionStatus: true,
        currentPeriodStart: true,
        currentPeriodEnd: true,
        dodoSubscriptionId: true,
        gracePeriodEnd: true,
        cancelAtPeriodEnd: true,
        planOverride: true,
        planOverrideStartsAt: true,
        planOverrideExpiresAt: true,
        grandfatheredUntil: true,
        isSuspended: true,
        deletionRequestedAt: true,
        gmailAuthorized: true,
        gmailPauseReason: true,
        gmailPauseUntil: true,
      },
    });
    expect(mocks.systemControl.findUnique).toHaveBeenCalledWith({
      where: { key: "global" },
      select: {
        sendingEnabled: true,
        paidGatingEnabled: true,
        gmailProjectPauseUntil: true,
      },
    });
    mocks.systemControl.findUnique.mockResolvedValue(control);
    await expect(
      requireEntitlement("owner", "csvImport"),
    ).rejects.toMatchObject({ code: "UPGRADE_REQUIRED" });
    expect(mocks.user.findUnique).toHaveBeenCalledTimes(2);
    expect(mocks.systemControl.findUnique).toHaveBeenCalledTimes(2);
  });
  it("uses the supplied transaction exclusively", async () => {
    const tx = {
      user: { findUnique: vi.fn().mockResolvedValue(user()) },
      systemControl: { findUnique: vi.fn().mockResolvedValue(legacy) },
    };
    await requireEntitlement(
      "transaction-owner",
      "send",
      tx as unknown as Prisma.TransactionClient,
    );
    expect(tx.user.findUnique.mock.calls[0][0].where).toEqual({
      id: "transaction-owner",
    });
    expect(tx.systemControl.findUnique).toHaveBeenCalledOnce();
    expect(mocks.user.findUnique).not.toHaveBeenCalled();
    expect(mocks.systemControl.findUnique).not.toHaveBeenCalled();
  });
  it("denies missing users and controls and propagates database failures", async () => {
    mocks.user.findUnique.mockResolvedValueOnce(null);
    await expect(requireEntitlement("missing", "send")).rejects.toMatchObject({
      code: "ACCOUNT_UNAVAILABLE",
    });
    expect(mocks.systemControl.findUnique).not.toHaveBeenCalled();
    mocks.systemControl.findUnique.mockResolvedValueOnce(null);
    await expect(requireEntitlement("owner", "send")).rejects.toMatchObject({
      code: "SYSTEM_CONTROL_UNAVAILABLE",
    });
    const failure = new Error("database unavailable");
    mocks.user.findUnique.mockRejectedValueOnce(failure);
    await expect(requireEntitlement("owner", "send")).rejects.toBe(failure);
    mocks.systemControl.findUnique.mockRejectedValueOnce(failure);
    await expect(requireEntitlement("owner", "send")).rejects.toBe(failure);
  });
  it.each([
    "ACCOUNT_UNAVAILABLE",
    "ACCOUNT_SUSPENDED",
    "SYSTEM_CONTROL_UNAVAILABLE",
    "SENDING_DISABLED",
    "GMAIL_RECONNECT_REQUIRED",
    "UPGRADE_REQUIRED",
  ] as const)("exposes stable %s errors", (code) => {
    const error = new EntitlementError(code);
    expect(error).toBeInstanceOf(AppError);
    expect(error.code).toBe(code);
    expect(error.name).toBe("EntitlementError");
    expect(error.message.length).toBeGreaterThan(0);
  });
});

describe.each(["blackThemes", "previewHighlightColors"] as const)(
  "Premium %s",
  (feature) => {
    it.each([control, legacy])(
      "uses effective access independently of rollout (%j)",
      (settings) => {
        for (const [account, at, allowed] of [
          [user(), now, false],
          [paid(), now, true],
          [paid(), end, false],
          [
            paid({ subscriptionStatus: "PAST_DUE", gracePeriodEnd: grace }),
            end,
            true,
          ],
          [
            paid({ subscriptionStatus: "PAST_DUE", gracePeriodEnd: grace }),
            grace,
            false,
          ],
          [
            user({
              planOverride: "PAID",
              planOverrideStartsAt: start,
              planOverrideExpiresAt: end,
            }),
            now,
            true,
          ],
          [
            user({
              planOverride: "PAID",
              planOverrideStartsAt: start,
              planOverrideExpiresAt: end,
            }),
            end,
            false,
          ],
          [
            paid({ planOverride: "FREE", planOverrideStartsAt: start }),
            now,
            false,
          ],
        ] as const) {
          expect(canUser(account, feature, settings, at).allowed).toBe(allowed);
          expect(
            getClientEntitlements(account, settings, at).features[feature],
          ).toBe(allowed);
        }
      },
    );
  },
);
